namespace App\Filament\Pages;

use App\Models\BrandSetting;
use Filament\Pages\Page;
use Illuminate\Http\Request;

class ManageBrandingSettings extends Page
{
    protected static ?string $navigationIcon = 'heroicon-o-paint-brush';
    public ?int $brandId = null;
    public ?BrandSetting $brandSetting = null;

    public function mount(Request $request): void
    {
        // Binds brand setting directly from query param without asserting tenant ownership
        $this->brandId = (int) $request->query('brand_id');
        $this->brandSetting = BrandSetting::find($this->brandId);
    }
}

corrected_code:
namespace App\Filament\Pages;

use App\Models\BrandSetting;
use Filament\Pages\Page;
use Filament\Facades\Filament;

class ManageBrandingSettings extends Page
{
    protected static ?string $navigationIcon = 'heroicon-o-paint-brush';
    public ?BrandSetting $brandSetting = null;

    public function mount(): void
    {
        $tenant = Filament::getTenant();
        $this->brandSetting = $tenant->brandSetting ?? BrandSetting::create(['tenant_id' => $tenant->id]);
    }
}
